/* Report 0x31. In audio mode the rumble bits are the writer's to clear, so that
 * a game's rumble or reset command cannot stop the haptics; out of it the pad
 * rumbles with the game's last motor values. */
static void bt_control(struct bt_pad *pad, const BYTE *payload, BOOL audio)
{
    BYTE report[78] = {0x31};

    report[1] = (pad->seq++ & 15) << 4;
    report[2] = 0x10;
    if (payload) memcpy(report + 3, payload, 47);
    if (pad_option("motor_power=full"))
    {
        report[4] |= 0x40;
        report[39] = 0;
    }
    if (audio)
    {
        report[3] &= ~3;
        report[5] = report[6] = 0;
    }
    else
    {
        report[3] |= 3;
        report[5] = pad->motors[0];
        report[6] = pad->motors[1];
    }
    report[41] &= ~4;
    bt_write(pad, report, sizeof(report));
}

motors.code:
/* rumble=haptics: the game's motor values played on the actuators instead of
 * the motors, for a game that rumbles and plays no haptics of its own (an XInput
 * title). The heavy motor becomes a 65 Hz tone on the left actuator and the
 * light one a 160 Hz tone on the right, 64 frames a block, the amplitude ramped
 * across the block from the last so a step does not click; as NotProton's
 * controller bridge did (fork/controllers, PCM.h DSBRumbleSynthBlock). A motor
 * value under 4 of 255 renders nothing. Real haptics from the game win. */
static void bt_synth(struct bt_pad *pad, BYTE heavy, BYTE light, signed char out[128])
{
    static const double hz[2] = {65.0, 160.0};
    /* The haptics' strength over Bluetooth applies to the tone as to the game's own haptics, up to full scale. */
    const float target[2] = {heavy < 4 ? 0 : fminf(1, heavy / 255.f * pad->synth_gain),
                             light < 4 ? 0 : fminf(1, light / 255.f * pad->synth_gain)};
    unsigned int i, ch;
    float amplitude;
    double v;

    for (i = 0; i < 64; i++)
        for (ch = 0; ch < 2; ch++)
        {
            amplitude = pad->synth_level[ch] + (target[ch] - pad->synth_level[ch]) * (i + 1) / 64.f;
            v = sin(pad->synth_phase[ch]) * amplitude * 127;
            out[2 * i + ch] = (signed char)lrint(fmax(-127, fmin(127, v)));
            pad->synth_phase[ch] += 2 * M_PI * hz[ch] / 3000;
            if (pad->synth_phase[ch] >= 2 * M_PI) pad->synth_phase[ch] -= 2 * M_PI;
        }
    pad->synth_level[0] = target[0];
    pad->synth_level[1] = target[1];
}

dualshock4.code:
/* The pad's input report 0x01 (64 bytes: on a cable as it comes, over
 * Bluetooth as patch 0004 makes it of 0x31) as a DualShock 4's 0x01 (64).
 * `counter` counts the reports; its low 6 bits are the DualShock 4's own
 * counter, under the PS and touchpad buttons.
 *
 *   DualSense                         DualShock 4
 *   1-4 LX LY RX RY                   1-4 the same
 *   5, 6 L2, R2 (analog)              8, 9
 *   8 hat and face buttons            5, the same bits
 *   9 L1 R1 L2 R2 Create Options L3 R3   6, the same bits (Create is Share)
 *   10 bit 0 PS, bit 1 touchpad       7, with the counter in bits 2-7; mute and
 *                                     the Edge's Fn and back buttons have nowhere to go
 *   16-21 gyro, 22-27 accelerometer   13-18, 19-24, the raw values unscaled
 *   28-31 timestamp, le32, 1/3 us     10-11, le16, 16/3 us: divided by 16
 *   32 (SDL: temperature)             12, sensor temperature
 *   33-36, 37-40 two touch points     33 one touch report, 34 its stamp, 35-42 the
 *                                     points, Y scaled from 1080 to 942
 *   53 battery level, charge state    30 level, bit 4 the cable
 *
 * The gyro and accelerometer values are copied as the sensors give them, not
 * rescaled. A reader turns them into degrees a second and g with the pad's
 * calibration, and the DualShock 4's feature report 0x02 carries the
 * DualSense's own 0x05 (see ds4_feature_reply), which Linux parses at the same
 * offsets for both pads (dualshock4_get_calibration_data,
 * dualsense_get_calibration_data). When that read failed, ViGEmBus's
 * DualShock 4 calibration stands in, and the raw DualSense values are read
 * with it.
 */
static inline void ds4_input_from_dualsense(const uint8_t ds[64], uint8_t ds4[64], uint8_t counter)
{
    uint8_t level = ds[53] & 0x0f, charge = ds[53] >> 4;
    uint32_t stamp;
    unsigned int i, y;

    memset(ds4, 0, DS4_INPUT_SIZE);
    ds4[0] = DS4_INPUT_ID;
    memcpy(ds4 + 1, ds + 1, 4);
    ds4[5] = ds[8];
    ds4[6] = ds[9];
    ds4[7] = (ds[10] & 0x03) | (uint8_t)((counter & 0x3f) << 2);
    ds4[8] = ds[5];
    ds4[9] = ds[6];
    stamp = (ds[28] | (ds[29] << 8) | (ds[30] << 16) | ((uint32_t)ds[31] << 24)) / 16;
    ds4[10] = stamp & 0xff;
    ds4[11] = (stamp >> 8) & 0xff;
    ds4[12] = ds[32];
    memcpy(ds4 + 13, ds + 16, 12);

    /* The DualSense's charge state (hid-playstation.c, dualsense_parse_report):
     * 0 on battery, 1 charging, 2 full, 0xa and 0xb a voltage or temperature
     * error, 0xf a charge error. The DualShock 4's (dualshock4_parse_report):
     * the level 0-10 alone on battery; with the cable bit, 0-10 charging, 11
     * full, 14 not charging for voltage or temperature, 15 a charge error. */
    if (level > 10) level = 10;
    switch (charge)
    {
    case 0x0: ds4[30] = level; break;
    case 0x1: ds4[30] = 0x10 | level; break;
    case 0x2: ds4[30] = 0x10 | 11; break;
    case 0xa:
    case 0xb: ds4[30] = 0x10 | 14; break;
    default:  ds4[30] = 0x10 | 15; break;
    }
    /* Byte 31 stays 0: its bit 2 says a wireless adapter lost its pad, and SDL
     * drops a report that has it. */

    ds4[33] = 1;
    ds4[34] = counter;
    for (i = 0; i < 2; i++)
    {
        const uint8_t *from = ds + 33 + 4 * i;
        uint8_t *to = ds4 + 35 + 4 * i;

        y = ((from[2] >> 4) | (from[3] << 4)) * DS4_TOUCHPAD_HEIGHT / DS_TOUCHPAD_HEIGHT;
        to[0] = from[0];  /* the contact: bit 7 set when the finger is up, on both pads */
        to[1] = from[1];
        to[2] = (from[2] & 0x0f) | (uint8_t)((y & 0x0f) << 4);
        to[3] = (uint8_t)(y >> 4);
    }
    /* The two touch reports not sent, their contacts up, as ViGEmBus's own
     * empty report has them. */
    ds4[44] = ds4[48] = ds4[53] = ds4[57] = 0x80;
}

cap-haptics.code:
/* Apple's USB audio driver puts the device's location ID in the endpoint's UID:
 * "AppleUSBAudioEngine:<manufacturer>:<product>:<location ID in hex>:<interface>".
 * winebus.sys builds the same container from that location ID for the device's HID
 * functions, so that games can pair a controller with its audio output; keep the
 * two in sync. */
static BOOL get_usb_container_id(const char *device, GUID *guid)
{
    static const GUID usb_location_base = {0, 0x27f2, 0x4948, {0x96, 0x54, 0x15, 0x28, 0x04, 0xaf, 0x63, 0x78}};
    static const char prefix[] = "AppleUSBAudioEngine:";
    const char *start, *end;
    unsigned long location;
    char *parsed;

    if(strncmp(device, prefix, strlen(prefix)) || !(end = strrchr(device, ':')))
        return FALSE;
    for(start = end; start > device && start[-1] != ':'; start--);
    location = strtoul(start, &parsed, 16);
    if(parsed != end || !location || location > 0xffffffff)
        return FALSE;

    *guid = usb_location_base;
    guid->Data1 = location;
    return TRUE;
}

